/*
 * A288530  Triangle read by rows in reverse order: T(n,k), (0 <= k <= n), in
 *          which each term is the least nonnegative integer such that no row,
 *          column, diagonal, or antidiagonal contains a repeated term.
 * https://oeis.org/A288530
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, look, tabl
 * Formula:   a(n) is generated by building the triangle T(n,k) (0 ≤ k ≤ n)
 *            with the greedy rule: at each cell choose the smallest
 *            non‑negative integer that does not already appear in the same
 *            row, column, main diagonal (n−k constant), or anti‑diagonal (n+k
 *            constant). The sequence is read by rows in reverse or...
 * Range:     u8 n <= 8838, u16 n <= 8838, u32 n <= 8838, u64 n <= 8838,
 *            u128 n <= 8838, big any n
 * Helpers:   compute_needed_row
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* C11 compatible implementation that builds the triangle
   incrementally and keeps all values in memory up to the
   largest n that has been requested.  The sets used to test
   for repeated values are implemented as growing bitsets. */

#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include "../utils/compute_needed_row.h"

/* ---------- Bitset implementation ------------------------------------- */

typedef struct {
    uint64_t *w;   /* words holding bits */
    size_t  cap;   /* number of words allocated */
} BitSet;

static void bitset_set(BitSet *bs, size_t v)
{
    size_t idx = v >> 6;
    if (idx >= bs->cap) {
        size_t newcap = idx + 1;
        bs->w = (uint64_t *)realloc(bs->w, newcap * sizeof(uint64_t));
        for (size_t i = bs->cap; i < newcap; ++i) bs->w[i] = 0ULL;
        bs->cap = newcap;
    }
    bs->w[idx] |= 1ULL << (v & 63);
}

static int bitset_test(const BitSet *bs, size_t v)
{
    size_t idx = v >> 6;
    if (idx >= bs->cap) return 0;
    return (int)((bs->w[idx] >> (v & 63)) & 1ULL);
}

static void bitset_clear(BitSet *bs)
{
    free(bs->w);
    bs->w = NULL;
    bs->cap = 0U;
}

/* ---------- Dynamic arrays of BitSet --------------------------------- */

typedef struct {
    BitSet *data;
    size_t  cap;   /* number of allocated elements */
} BitSetArray;

static void bsarray_init(BitSetArray *a) { a->data = NULL; a->cap = 0U; }

static void bsarray_ensure(BitSetArray *a, size_t idx)
{
    if (idx >= a->cap) {
        size_t newcap = idx + 1;
        a->data = (BitSet *)realloc(a->data, newcap * sizeof(BitSet));
        for (size_t i = a->cap; i < newcap; ++i) {
            a->data[i].w   = NULL;
            a->data[i].cap = 0U;
        }
        a->cap = newcap;
    }
}

static void bsarray_clear(BitSetArray *a)
{
    for (size_t i = 0; i < a->cap; ++i) bitset_clear(&a->data[i]);
    free(a->data);
    a->data = NULL;
    a->cap  = 0U;
}

/* ---------- Global data ---------------------------------------------- */

static BitSetArray g_cols;   /* column groups */
static BitSetArray g_diags;  /* main diagonals */
static BitSetArray g_antis;  /* anti diagonals */

static seq_t *g_seq  = NULL; /* sequence array a(n) */
static size_t g_seq_len = 0;
static size_t g_seq_cap = 0;

static size_t g_rows_computed = 0; /* number of rows built (0 means none) */

/* ---------- Helper functions ----------------------------------------- */

static void add_value(seq_t v)
{
    if (g_seq_len == g_seq_cap) {
        g_seq_cap = (g_seq_cap == 0) ? 1 : g_seq_cap * 2;
        g_seq = (seq_t *)realloc(g_seq, g_seq_cap * sizeof(seq_t));
    }
    g_seq[g_seq_len++] = v;
}

static void build_to_row(size_t r)
{
    for (size_t i = g_rows_computed; i <= r; ++i) {
        /* ensure data structures large enough */
        bsarray_ensure(&g_cols,  i);
        bsarray_ensure(&g_diags, i);
        bsarray_ensure(&g_antis, 2*i);

        /* local bitset for the current row */
        BitSet row_used = { NULL, 0U };

        for (int k = (int)i; k >= 0; --k) {
            size_t v = 0;
            while (bitset_test(&g_cols.data[k],   v) ||
                   bitset_test(&g_diags.data[i-k], v) ||
                   bitset_test(&g_antis.data[i+k], v) ||
                   bitset_test(&row_used,          v)) {
                ++v;
            }
            /* record the value */
            bitset_set(&g_cols.data[k],   v);
            bitset_set(&g_diags.data[i-k], v);
            bitset_set(&g_antis.data[i+k], v);
            bitset_set(&row_used,          v);
            add_value((seq_t)v);
        }
        bitset_clear(&row_used); /* free temporary bitset words */
        g_rows_computed = i + 1;
    }
}

/* ---------- Main required function ----------------------------------- */

seq_t a(idx_t n)
{
    /* initialise global structures once */
    static int initialized = 0;
    if (!initialized) {
        bsarray_init(&g_cols);
        bsarray_init(&g_diags);
        bsarray_init(&g_antis);
        initialized = 1;
    }

    /* determine which row contains index n */
    size_t row = compute_needed_row(n);

    /* build triangle up to that row if necessary */
    if (row >= g_rows_computed) {
        build_to_row(row);
    }

    /* a(n) is the n‑th element in the linearized sequence */
    return g_seq[(size_t)n];
}
